using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using ExposureUnnoticed2.Master.Cosplay;using ExposureUnnoticed2.Master.Item;using ExposureUnnoticed2.ObjectUI.InventoryPanel;using ExposureUnnoticed2.Scripts.InGame;using UnityEngine;
namespace SfmMvp{
[DefaultExecutionOrder(100)]public sealed class CoreGameplaySmoke:MonoBehaviour{
 [Serializable]public sealed class Row{public string category,key,result;public int price,count;public double before,after,spent;}
 [Serializable]public sealed class Report{public bool passed,methodHooks,originalSavesAccessed,originalConstructors;public string failure,gameSHA256;public int checks,startFrame,endFrame;public double originalStartingRp,qaFundsAdded;public List<Row> purchases=new List<Row>();public List<string> checksPassed=new List<string>(),errors=new List<string>();public string[] scope;}
 readonly Report r=new Report();CoreGameplayPanel panel;CoreGameplayData data;OriginalMovementMvpBridge bridge;string output;bool enabledByArg;
 void Need(bool b,string n){r.checks++;if(!b)throw new Exception(n);r.checksPassed.Add(n);}
