 void Error(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)r.errors.Add(t+":"+m);}
 void Capture(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();try{Need(t!=null,"Real rendered core screenshot");File.WriteAllBytes(Path.Combine(output,name+".png"),t.EncodeToPNG());}finally{if(t)Destroy(t);}}
 IEnumerator Start(){var args=Environment.GetCommandLineArgs();enabledByArg=Array.IndexOf(args,"-sfmCoreSmoke")>=0;if(!enabledByArg)yield break;Application.logMessageReceived+=Error;
  try{int k=Array.IndexOf(args,"-sfmActionOutput");Need(k>=0&&k+1<args.Length,"Bound action output required");output=Path.GetFullPath(args[k+1]);Need(Directory.Exists(output)&&!File.Exists(Path.Combine(output,"core-gameplay.json")),"Existing owned action output and fresh core report");panel=GetComponent<CoreGameplayPanel>();data=GetComponent<CoreGameplayData>();bridge=GetComponent<OriginalMovementMvpBridge>();Need(panel&&panel.Ready&&data&&data.Initialized&&bridge&&bridge.Ready,"Core panel and actual original actor graph ready");r.gameSHA256=Hash(typeof(GameStateFacade).Assembly.Location);r.originalConstructors=bridge.UsesOriginalConstructors;Need(r.originalConstructors,"Actual original PCA/data/state constructors used");r.originalStartingRp=GameState.GameStateData.CurrentRp;Need(r.originalStartingRp==0,"Original constructor starts with zero spendable RP");r.startFrame=Time.frameCount;panel.SetOpen(true);panel.AddTestFunds();panel.AddTestFunds();r.qaFundsAdded=1000;Need(GameState.GameStateData.CurrentRp==1000,"Two explicit UI test-fund commands seed1000 RP");
  }catch(Exception e){Finish(e);yield break;}
  yield return null;
  for(int category=0;category<7;category++){
   Exception failure=null;try{var record=data.Catalog(category).First(x=>!data.Owned(x));var state=GameState.GameStateData;var row=new Row{category=category.ToString(),key=record.NameKey,price=record.Price,before=state.CurrentRp};double spentBefore=state.StatistisTotalUseRp;row.result=data.Purchase(record);row.after=state.CurrentRp;row.spent=state.StatistisTotalUseRp-spentBefore;row.count=data.Count(record);r.purchases.Add(row);Need(row.result=="购买成功"&&row.after==row.before-row.price&&row.spent==row.price,"Original native purchase debit/spend/complete category"+category);Need(data.Owned(record)&&row.count>0,"Original ownership updated category"+category);Need(data.Shop.CurrentRecord==null,"Full original purchase entry returned category"+category);Need(bridge.Ready,"Original frame remains ready after purchase category"+category);}catch(Exception e){failure=e;}if(failure!=null){Finish(failure);yield break;}yield return null;
  }
  try{
   var state=GameState.GameStateData;var unavailable=data.Catalog(2).First(x=>!data.Owned(x));double balance=state.CurrentRp,spend=state.StatistisTotalUseRp;state.CurrentRp=unavailable.Price-0.25;Need(data.Purchase(unavailable)=="RP 不足"&&!data.Owned(unavailable)&&state.CurrentRp==unavailable.Price-0.25&&state.StatistisTotalUseRp==spend,"Insufficient funds reject without mutation on same actor");state.CurrentRp=balance;
   var repeat=data.Catalog(5).Cast<MItemRecord>().First(x=>!x.IsValuables);state.ItemDict[repeat.Type]=99;Need(data.Purchase(repeat)=="数量已达上限"&&data.Count(repeat)==99&&state.CurrentRp==balance,"99 item limit rejects in actual combined graph");state.ItemDict[repeat.Type]=98;Need(data.Purchase(repeat)=="购买成功"&&data.Count(repeat)==99&&state.CurrentRp==balance-repeat.Price,"98 allows99th on same actor");
   int capacity=data.CapacityCount();Need(capacity==5&&data.Inventory.CanEquipByMaxCount(),"Original level0 capacity and below-limit rule");var snapshot=new Dictionary<int,bool>(state.PlayerCosplayPartsDict);foreach(var p in MCosplay.GetAll().Values.SelectMany(x=>x.GetAll()).Where(x=>!state.PlayerCosplayPartsDict.TryGetValue(x.UniqueId,out bool active)||!active).Take(capacity))GameStateFacade.SetActiveCosplayParts(p.UniqueId,true);Need(!data.Inventory.CanEquipByMaxCount(),"Original inventory rejects equip at/over capacity");state.PlayerCosplayPartsDict=snapshot;Need(data.Inventory.CanEquipByMaxCount(),"Restoring actual inventory releases capacity");Need(bridge.Ready&&r.errors.Count==0,"No original frame failure or Unity errors after all purchases");
  }catch(Exception e){Finish(e);yield break;}
  yield return new WaitForEndOfFrame();try{Capture("core-shop");panel.SetInventoryPage();}catch(Exception e){Finish(e);yield break;}yield return new WaitForEndOfFrame();try{Capture("core-inventory");r.endFrame=Time.frameCount;r.passed=true;Finish(null);}catch(Exception e){Finish(e);}
 }
 void Finish(Exception failure){if(failure!=null)r.failure=failure.ToString();r.scope=new[]{"Same actual original actor constructors, original default active part20011, original fifteen master assets, real native movement/action main and eighteen merged original equipment/shop methods","Seven actual priced categories and budget/item-cap/inventory-capacity paths use the same data.Purchase callback as the temporary UI; no Game/Core hooks","1000 RP was explicitly seeded by two owned test-fund UI commands, not recovered new-game economy or mission settlement","Owned test panel, hidden finite presentation material/part inputs; real equipment transaction/appearance/body/mission/NPC UI integration remains incomplete"};Application.logMessageReceived-=Error;if(output!=null)File.WriteAllText(Path.Combine(output,"core-gameplay.json"),JsonUtility.ToJson(r,true)+"\n");if(!r.passed){Debug.LogError("SFM_CORE_SMOKE "+r.failure);Application.Quit(4);}}
}
}
